import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as i,a as s}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const m=JSON.parse('{"title":"Prerequisites","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md"}'),o={name:"getting-started/index.md"};function r(n,e,c,d,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><p>The only runtime prerequisite is a <strong>GitHub personal access token</strong> (or the <a href="https://cli.github.com/" target="_blank" rel="noreferrer">GitHub CLI</a>, see below). The pre-compiled binary is self-contained and has no runtime dependency — you do not need Bun to run it.</p><div class="tip custom-block"><p class="custom-block-title">Building from source?</p><p>If you want to build <code>github-code-search</code> from source, you will additionally need <a href="https://bun.sh" target="_blank" rel="noreferrer">Bun</a> ≥ 1.4. See the <a href="/github-code-search/v2/getting-started/installation.html#from-source">Installation guide</a>.</p></div><h2 id="github-token" tabindex="-1">GitHub token <a class="header-anchor" href="#github-token" aria-label="Permalink to &quot;GitHub token&quot;">​</a></h2><p>A GitHub personal access token (PAT) is required to call the GitHub code search API.</p><h3 id="required-scopes" tabindex="-1">Required scopes <a class="header-anchor" href="#required-scopes" aria-label="Permalink to &quot;Required scopes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>When needed</th></tr></thead><tbody><tr><td><code>repo</code></td><td>Searching <strong>private</strong> repositories</td></tr><tr><td><code>public_repo</code></td><td>Searching public repositories only</td></tr><tr><td><code>read:org</code></td><td>Using <a href="/github-code-search/v2/usage/team-grouping.html"><code>--group-by-team-prefix</code></a> to group results by team</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Classic vs fine-grained tokens</p><p>Both token types work. Classic tokens are simpler to configure for org-wide searches. Fine-grained tokens require explicit repository access per repo, which is impractical for org-wide searches.</p></div><h3 id="set-the-token" tabindex="-1">Set the token <a class="header-anchor" href="#set-the-token" aria-label="Permalink to &quot;Set the token&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;"> GITHUB_TOKEN</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">ghp_xxxxxxxxxxxxxxxxxxxx</span></span></code></pre></div><p>Add this to your shell profile (<code>~/.zshrc</code>, <code>~/.bashrc</code>, <code>~/.config/fish/config.fish</code>, …) to make it permanent.</p><div class="warning custom-block"><p class="custom-block-title">Token security</p><p>Never commit your token to version control. Use environment variables or a secrets manager.</p></div><div class="tip custom-block"><p class="custom-block-title">Already using the GitHub CLI?</p><p>If <code>GITHUB_TOKEN</code> isn&#39;t set and <a href="https://cli.github.com/" target="_blank" rel="noreferrer"><code>gh</code></a> is installed and authenticated (<code>gh auth login</code>), <code>github-code-search</code> automatically retrieves a token via <code>gh auth token</code> — no extra setup needed. Applies to the search commands and the <code>upgrade</code> subcommand.</p></div><h2 id="default-organization" tabindex="-1">Default organization <a class="header-anchor" href="#default-organization" aria-label="Permalink to &quot;Default organization&quot;">​</a></h2><p>If you mostly search a single organization, set <code>GCS_DEFAULT_ORG</code> once to omit <code>--org</code> on every call:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;"> GCS_DEFAULT_ORG</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">my-org</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span></span></code></pre></div><p>An explicit <code>--org</code> flag always takes precedence over <code>GCS_DEFAULT_ORG</code>. See <a href="/github-code-search/v2/reference/environment.html">Environment variables</a> for details.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>→ <a href="/github-code-search/v2/getting-started/installation.html">Install github-code-search</a></p>`,19)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
